## Section1(not reported)
## Problem1(1.3.5.11)
## Author()
## Institution()
## Language(en-US)

DOCUMENT();

############################################################
# Load Macros
############################################################
loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PCCmacros.pl",
  "bizarroArithmetic.pl",
  "contextForm.pl",
  "contextFraction.pl",
  "APEX.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

############################################################
# Header
############################################################

############################################################
# PG Setup Code
############################################################
$lb = 1;
$ub = random(3,5,1);
if($envir{problemSeed}==1){$ub=4;};
Context()->variables->are(i=>'Real');
$f = Formula("1/i - 1/(i+1)")->reduce;
@i = ($lb..$ub);
Context("Fraction");
@fi = map{Fraction($f->eval(i=>$_))}(@i);
$string = join('+',@fi);
$sum = Fraction($string);
Context("Form");
Context()->operators->set(
  '+' => {class => 'bizarro::BOP::add', isCommand => 1},
  '-' => {class => 'bizarro::BOP::subtract', isCommand => 1},
);
$terms = Formula("$string");

############################################################
# Body
############################################################

BEGIN_PGML
Write out each term of the summation and compute the sum.

[`\sum\limits_{i=[$lb]}^{[$ub]} \left([$f]\right)`]

[@KeyboardInstructions('Enter the sum of terms here. For example, [|1+2+3|]*.')@]**

[_]{$terms}{20}

[@KeyboardInstructions('Enter the actual sum here.')@]**

[_]{$sum}{20}

END_PGML

############################################################
# End Problem
############################################################

ENDDOCUMENT();
